"""Human-readable views of conditional rental-project calculations. MIT."""
from decimal import Decimal
import csv
import html
import io
import json


def project(req,result):
    currency=lambda x:'$'+format(Decimal(x),',.2f')
    annual=result['annual']
    headers=['Year','Effective income','Operating expenses','Replacement reserve','NOI for coverage','Primary debt service','Other debt service','Required DSCR','DSCR','Maturity principal','Cash after all modeled deductions']
    rows=[[x['calendar_year'],currency(x['effective_gross_income_usd']),currency(x['operating_expenses_usd']),currency(x['replacement_reserve_usd']),currency(x['coverage_noi_usd']),currency(x['primary_debt_service_usd']),currency(x['other_debt_service_usd']),x['required_dscr'] if x['required_dscr'] is not None else 'N/A',x['dscr'] if x['dscr'] is not None else 'No debt service',currency(x['maturity_principal_due_usd']),currency(x['cash_after_reserves_debt_and_below_line_usd'])] for x in annual]
    overview=[('Proposed homes (scenario, not validated layout)',str(req['program']['homes'])),('Proposed gross area sf',req['program']['gross_area_sf']),('Total development cost',currency(result['total_development_cost_usd'])),('Maximum primary loan capacity under declared financing caps',currency(result['maximum_primary_loan_capacity_usd'])),('Modeled primary loan limited to scenario funding need (uncommitted)',currency(result['modeled_primary_loan_usd'])),('Declared other sources, committed + proposed',currency(result['all_declared_other_sources_usd'])),('Unallocated capital after modeled loan and all declared sources',currency(result['unallocated_capital_after_modeled_loan_and_all_declared_sources_usd'])),('Capital not covered by committed sources',currency(result['capital_not_covered_by_committed_sources_usd'])),('Balloon at loan maturity',currency(result['balloon_at_term_usd']))]
    def mdtable(h,rs):return '\n'.join(['| '+' | '.join(h)+' |','| '+' | '.join(['---']*len(h))+' |']+['| '+' | '.join(str(x).replace('|','/').replace('\n',' ') for x in r)+' |' for r in rs])
    lines=['# Rental underwriting: '+req['id'],'',req['question'],'',result['meaning'],'','**Price basis:** '+req['price_basis'],'','**Input basis:** '+req['basis']['rationale'],'',mdtable(['Quantity','Value'],overview),'','## Annual cash flow','',mdtable(headers,rows),'','Replacement reserves are deducted from coverage NOI: '+str(req['operations']['reserve_deducted_for_coverage'])+'. The cash-flow calculation deducts them exactly once.','',f"Debt sized against years 1–{result['debt_sizing_years']}; binding constraints: "+', '.join(result['binding_debt_caps'])+'.','', 'Coverage breach years: '+(', '.join(map(str,result['coverage_breach_years'])) or 'None under the supplied assumptions.')]
    lines+=['','Cash-shortfall years (including modeled maturity obligations): '+(', '.join(map(str,result['cashflow_shortfall_years'])) or 'None under supplied assumptions.'),'','## Capital budget','',mdtable(['Category','Amount','Input measure'],[[x['category'],currency(x['amount_usd']),x['measure']] for x in result['capital_lines']]),'','## Unresolved checks','']+['- '+x for x in result['missing_financing_checks']+result['unresolved']]
    lines+=['','## Declared references','']+[f"- [{x['title']}]({x['url']}): {x['locator']}" for x in req['references']]
    lines+=['','Source files, if supplied, are copied and hashed under sources/. Declared references without retained bytes are identified in references.json. Attribution and hashes do not establish a professional interpretation.','', 'Full calculations and input bases: request.json, results.json, trace.json and annual.csv.']
    esc=lambda x:html.escape(str(x))
    def table(h,rs):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in r)+'</tr>' for r in rs)+'</tbody></table></div>'
    body='<h1>'+esc(req['id'])+'</h1><p>'+esc(req['question'])+'</p><p>'+esc(result['meaning'])+'</p><p><b>Price basis:</b> '+esc(req['price_basis'])+'</p>'+table(['Quantity','Value'],overview)+'<h2>Annual cash flow</h2>'+table(headers,rows)
    body+='<p>Replacement reserve is deducted once from cash flow. Coverage treatment: '+esc(req['operations']['reserve_deducted_for_coverage'])+'.</p><p>Binding debt caps: '+esc(', '.join(result['binding_debt_caps']))+'. Coverage breach years: '+esc(result['coverage_breach_years'])+'.</p><h2>Capital uses</h2>'+table(['Category','Amount'],[[x['category'],currency(x['amount_usd'])] for x in result['capital_lines']])
    body+='<h2>Unresolved checks</h2><ul>'+''.join('<li>'+esc(x)+'</li>' for x in result['missing_financing_checks']+result['unresolved'])+'</ul><details><summary>Inputs, rationale and declared references</summary><pre>'+esc(json.dumps(req,indent=2,sort_keys=True))+'</pre></details>'
    page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rental underwriting</title><style>body{font:16px/1.5 system-ui;max-width:1200px;margin:30px auto;padding:0 20px;background:#fafaf7;color:#17303a}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #cdd5d8;padding:9px;text-align:left}th{background:#e5eeed}pre{white-space:pre-wrap;overflow-wrap:anywhere}details{background:white;padding:14px}</style>'+body+'</html>'
    output=io.StringIO();fields=[k for k in annual[0] if k not in ['income_lines','expense_lines']];w=csv.DictWriter(output,fieldnames=fields,lineterminator='\n');w.writeheader()
    for row in annual:w.writerow({k:row[k] for k in fields})
    return {'packet.md':'\n'.join(lines)+'\n','packet.html':page,'annual.csv':output.getvalue()}
